sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var qtrackenv = gs.getProperty('x_hsb11_hsbcmss_qw.qtrack_url');
	var qtrackToken = gs.getProperty('x_hsb11_hsbcmss_qw.qtrack_api_token');
    try {
        //var taskid = current.servicenow_task_id;

        var tasknumber = current.servicenow_task_id;
        var taskid;
        if (tasknumber == '') {
            taskid = 'NA';
        } else {
            taskid = tasknumber;
        }

        var email_status = current.email_status;
        var qtrack = current.qtrack_id;

        var r = new sn_ws.RESTMessageV2('HSBC QTrack outbound email status', 'Default Put');
        current.state = 'Processing';

        r.setStringParameterNoEscape('qtrack_base_uri', qtrackenv);
		r.setStringParameterNoEscape('qtrack_token',qtrackToken);
        r.setStringParameterNoEscape('serviceNowId', taskid.toString());
        r.setStringParameterNoEscape('status', email_status.toString());
        r.setStringParameterNoEscape('queryMailId', qtrack.toString());



        var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        if (httpStatus == '200') {

            current.response_body = responseBody;
            current.response_date = new GlideDateTime();
            current.state = "Processed";
        } else {

            current.error_code = httpStatus;
            current.error_body = responseBody;
            current.state = 'Error';
        }
    } catch (ex) {
        var message = ex.message;
    }

    current.update();
})(current, previous);
